def check_triple(a, b, c):
    # Equation: a^3 (b^3 + c^3 ) = 2012 (abc+2)
    lhs = a**3 * (b**3 + c**3)
    rhs = 2012 * (a * b * c + 2)
    return lhs == rhs

print("Searching for solutions (a, b, c) where 1 <= a <= b <= c <= 10...")
found_solutions = []
for a in range(1, 11):
    for b in range(a, 11):
        for c in range(b, 11):
            if check_triple(a, b, c):
                found_solutions.append((a, b, c))
                print(f"Solution found: ({a}, {b}, {c})")

if not found_solutions:
    print("No solutions found in the range 1 <= a <= b <= c <= 10.")
else:
    print(f"Found solutions: {found_solutions}")

